// RESPONSIBILITY: Defines runtime validation schemas for communication_notices_and_announcements; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_communication/communication_notices_and_announcements/schemas/AdminCommunicationNoticesAndAnnouncementsSchemas.ts)

import { isValid, parseISO } from 'date-fns';
// Generated by ts-to-zod
import { z } from "zod";

export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

export const announcementStatusSchema = z.union([z.literal("active"), z.literal("scheduled"), z.literal("expired"), z.literal("draft")]);

export const announcementPrioritySchema = z.union([z.literal("high"), z.literal("medium"), z.literal("low")]);

export const announcementAudienceSchema = z.union([z.literal("all"), z.literal("members"), z.literal("managers"), z.literal("trainers"), z.literal("staff")]);

export const announcementSchema = z.object({
    id: z.string(),
    title: z.string(),
    body: z.string(),
    priority: announcementPrioritySchema,
    status: announcementStatusSchema,
    audience: z.array(announcementAudienceSchema),
    gymIds: z.array(z.string()),
    gymNames: z.array(z.string()),
    publishedAt: z.string().refine((value) => isValid(parseISO(value)), 'announcements.validation.invalidPublishedAt'),
    expiresAt: z.string().refine((value) => isValid(parseISO(value)), 'announcements.validation.invalidExpiresAt'),
    createdBy: z.string(),
    createdAt: z.string(),
    viewCount: z.number(),
    viewsByBranch: z.array(z.object({
        branchId: z.string(),
        count: z.number()
    })).optional(),
    isPinned: z.boolean(),
    deliveryStatus: z.string().optional(),
    pushNotificationSent: z.boolean().optional(),
    acknowledgedCount: z.number().optional()
});

export const announcementFormValuesSchema = z.object({
    title: z.string().trim().min(1, 'announcements.validation.titleRequired').max(160, 'announcements.validation.titleTooLong'),
    body: z.string().trim().min(1, 'announcements.validation.bodyRequired').max(5000, 'announcements.validation.bodyTooLong'),
    priority: announcementPrioritySchema,
    audience: z.array(announcementAudienceSchema),
    gymIds: z.array(z.string()),
    publishedAt: z.string().refine((value) => isValid(parseISO(value)), 'announcements.validation.invalidPublishedAt'),
    expiresAt: z.string().refine((value) => isValid(parseISO(value)), 'announcements.validation.invalidExpiresAt'),
    isPinned: z.boolean()
}).superRefine((value, context) => {
    if (parseISO(value.expiresAt).getTime() < parseISO(value.publishedAt).getTime()) context.addIssue({ code: z.ZodIssueCode.custom, path: ['expiresAt'], message: 'announcements.validation.expiryBeforePublish' });
    if (value.audience.length === 0) context.addIssue({ code: z.ZodIssueCode.custom, path: ['audience'], message: 'announcements.validation.audienceRequired' });
    if (value.audience.includes('managers')) context.addIssue({ code: z.ZodIssueCode.custom, path: ['audience'], message: 'announcements.validation.invalidAudience' });
    if (value.gymIds.length === 0) context.addIssue({ code: z.ZodIssueCode.custom, path: ['gymIds'], message: 'announcements.validation.gymRequired' });
});

export const announcementKpiDataSchema = z.object({
    total: z.number(),
    active: z.number(),
    scheduled: z.number(),
    expired: z.number(),
    totalViews: z.number(),
    pinned: z.number()
});
